import {catalog} from './catalog.js';
import {icon} from './icons.js';
import {createAccountingUI} from './accounting-ui.js';
import * as inventory from './inventory.js';
import * as manufacturing from './manufacturing.js';
import * as assets from './assets.js';
import {PAGE_MAP,MODULE_HOME,PAGE} from './pages-map.js';
import {plannedPage,projectsScreen} from './screens.js';
import {createPortals,portalForPath,platformModules,portalTabs} from './portals.js';
import {createDetailedWorkspaces} from './workspaces.js';
import {escape as e,illustrate,searchIndex,cents,decimal} from './model.js';
const portal=portalForPath(location.pathname);
const root=document.querySelector('#design-root'),searchDialog=document.querySelector('#search-dialog'),detailDialog=document.querySelector('#detail-dialog');
const symbols=Object.fromEntries(catalog.modules.map(m=>[m.id,icon(m.id)]));
const primary={accounting:'ACC-003',banking:'ACC-006',payments:'SAL-007',sales:'SAL-003',purchases:'PUR-004',tax:'TAX-003',inventory:'INV-003',manufacturing:'MFG-004',pos:'POS-001',assets:'AST-003'};
const labels={reports:['report','Reports'],accounting:['journal','Journal entries'],banking:['transfer','Cash and bank movements'],payments:['payment','Payments and receipts'],sales:['invoice','Sales invoices'],purchases:['supplier bill','Supplier bills'],tax:['tax rule','Tax rules'],inventory:['stock movement','Stock movements'],manufacturing:['production order','Production orders'],pos:['sale','POS receipts'],assets:['depreciation','Asset events']};
const names={accounting:['Capital introduced','Monthly accrual','Office expenses'],banking:['Main bank transfer','Cash deposit','Bank reconciliation'],payments:['Atlas Studio · Receipt','Willow Supplies · Payment','Atlas Studio · Advance'],sales:['Atlas Studio','Linden Design','Harbor Workshop'],purchases:['Willow Supplies','Maple Packaging','Cedar Services'],tax:['Withholding review','Input recovery schedule','Output tax workpaper'],inventory:['Flour · Central store','Packaging · Workshop','Biscuit batch · Bakery'],manufacturing:['Butter biscuit · Batch 026','Bakery recipe · v3','Workshop assembly · WO-024'],pos:['Counter 01 · Walk-in','Bakery · Split tender','Counter 02 · Return'],assets:['Office equipment · EQ-001','Delivery vehicle · VH-004','Workshop tools · EQ-018']};
const records=catalog.modules.flatMap(m=>Array.from({length:6},(_,i)=>({id:'demo-'+m.id+'-'+i,module:m.id,reference:'DEMO-'+m.id.slice(0,3).toUpperCase()+'-'+String(1001+i),company:platformModules.has(m.id)?null:i%2?'Cedar Manufacturing':'Northstar Trading',name:names[m.id]?.[i%3]??m.title+' example '+(i+1),date:'2026-11-'+String(13-i).padStart(2,'0'),state:m.interactive?['Draft','Review needed','Posted example','Returned','Posted example','Draft'][i]:'Specification brief',amount:['sales','purchases','pos'].includes(m.id)?'198.00':m.id==='manufacturing'?'130.00':m.id==='assets'?'170.00':m.interactive?'200.00':'not applicable'})));
let demoCompany='Northstar Trading',demoBranch='All branches';
let route={module:'home',tab:'workspace',screen:'',mode:'',code:'',form:''},uiState='sample',role='Owner',sidebarCollapsed=false,mobileMenu=false,listSearch='',listStatus='',editorTab='document',draft={},dirty=false,history=[],historyIndex=-1,restoring=false;
let favorites;try{favorites=JSON.parse(localStorage.getItem('saven:design:v2:favorites')??'[]');if(!Array.isArray(favorites))favorites=[];document.documentElement.dataset.theme=localStorage.getItem('saven:design:v2:theme')??'light';}catch{favorites=[];}

const accountingUI=createAccountingUI({render,navigate:go,notify,dirty:value=>{dirty=value},getCompany:()=>demoCompany});
const portals=createPortals({render,navigate:go,notify});
const detailed=createDetailedWorkspaces({render,navigate:go,notify,dirty:value=>{dirty=value},getRole:()=>role,getCompany:()=>demoCompany});

function personaCan(mid){const allowed={Bookkeeper:['accounting','banking','payments','sales','purchases','tax','assets','reports','finance','drive','settings','subscription','projects','crm','design'],Storekeeper:['inventory','manufacturing','pos','assets','drive','offline','design'],Cashier:['pos','sales','payments','offline','design'],Operator:['admin','apps','offline','design']};return role==='Owner'||(allowed[role]??[]).includes(mid);}
function personaCatalog(){const modules=catalog.modules.filter(m=>personaCan(m.id)&&(portal==='business'?!platformModules.has(m.id):m.id===portal)),ids=new Set(modules.flatMap(m=>m.requirements));return {...catalog,modules,requirements:catalog.requirements.filter(r=>ids.has(r.id))};}
const module=()=>catalog.modules.find(m=>m.id===route.module),req=id=>catalog.requirements.find(r=>r.id===id),btn=(label,action,extra='',primary=false)=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${e(text)}</span>`;
function notify(text){const n=document.querySelector('#toast');n.textContent=text;n.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.remove('visible'),5000);}
function go(next){if(next.module==='operator'&&portal!=='operator'){location.assign('/operator/#'+new URLSearchParams(next));return;}if(next.module==='commerce'&&portal!=='commerce'){location.assign('/subscriptions/#'+new URLSearchParams(next));return;}if(portal!=='business'&&next.module&&next.module!==portal){location.assign('/#'+new URLSearchParams(next));return;}if(dirty&&!confirm('Discard this unsaved design draft? No business record has been saved.'))return;dirty=false;route={module:'home',tab:'workspace',screen:'',mode:'',code:'',form:'',...next};location.hash=new URLSearchParams(route).toString();if(location.hash.slice(1)===new URLSearchParams(route).toString())render();}
function readRoute(){const p=new URLSearchParams(location.hash.slice(1));route={module:p.get('module')||(portal==='business'?'home':portal),tab:p.get('tab')||'workspace',screen:p.get('screen')||'',mode:p.get('mode')||'',code:p.get('code')||'',form:p.get('form')||''};if(route.module!=='home'&&!module())route.module=portal==='business'?'home':portal;if(portal==='business'&&platformModules.has(route.module))route.module='home';if(portal!=='business'&&route.module!==portal)route.module=portal;if(route.screen&&!req(route.screen))route.screen='';if(route.module==='accounting'){if(!route.tab||route.tab==='workspace')route.tab='dashboard';if(route.tab==='register')route.tab='journals';}render();}
function remember(){if(restoring)return;const value=JSON.stringify(route);if(history[historyIndex]===value)return;history=history.slice(0,historyIndex+1);history.push(value);if(history.length>100)history.shift();historyIndex=history.length-1;}
function move(n){const i=historyIndex+n;if(i<0||i>=history.length)return;if(dirty&&!confirm('Discard this unsaved design draft?'))return;dirty=false;historyIndex=i;restoring=true;route=JSON.parse(history[i]);location.hash=new URLSearchParams(route).toString();render();restoring=false;}
function navigation(){if(portal!=='business')return `<div class="nav-label">${portal==='operator'?'Platform operations':'Commercial accounts'}</div>`+portalTabs[portal].map(([id,label])=>`<button class="nav-item" data-module="${portal}" data-tab="${id}" ${route.tab===id?'aria-current="page"':''}><span class="nav-symbol">${icon(id==='workspace'?'home':portal==='operator'?'admin':'payments')}</span>${label}</button>`).join('');let last='';return catalog.modules.filter(m=>PAGE_MAP[m.id]).map(m=>{let label=m.group!==last?`<div class="nav-label">${e(m.group)}</div>`:'';last=m.group;const pages=PAGE_MAP[m.id]||[];const children=m.id===route.module&&pages.length?`<div class="nav-children">${pages.map(([id,label,,state])=>`<button class="nav-child" data-module="${m.id}" data-tab="${id}" ${route.tab===id?'aria-current="page"':''}>${label}${state==='planned'?'':''}</button>`).join('')}</div>`:'';return label+`<button class="nav-item" data-module="${m.id}" title="${e(m.title)}" ${route.module===m.id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbols[m.id]}</span><span class="nav-text">${e(m.title)}</span>${m.id==='offline'?'<small>Later</small>':''}</button>`+children;}).join('');}

function render(){remember();if(portal==='business'&&route.module!=='home'&&!PAGE_MAP[route.module])route.module='accounting';if(!route.tab||route.tab==='workspace')route.tab=MODULE_HOME[route.module]||'workspace';if(route.module==='accounting'&&route.tab==='register')route.tab='journals';const m=module(),business=portal==='business';document.title='SA7EN | '+(business?m?.title??'Workspace':portal==='operator'?'Operator administration':'Subscriptions & onboarding');root.innerHTML=`<div class="shell ${mobileMenu?'menu-open':''} ${sidebarCollapsed?'sidebar-collapsed':''}"><aside class="sidebar" aria-label="${business?'Business workspace':portal==='operator'?'Operator':'Subscriptions'} navigation"><div class="brand">${sidebarCollapsed?`<button class="brand-mark" data-action="expand" aria-label="Expand sidebar" title="Expand sidebar"><span class="brand-logo" role="img" aria-label="SA7EN"></span></button>`:`<span class="brand-logo" role="img" aria-label="Economic Systems"></span><div><strong>SA7EN</strong><small>${business?'':portal==='operator'?'PLATFORM OPERATIONS':'SUBSCRIPTIONS & BILLING'}</small></div><button class="sidebar-arrow" data-action="collapse" aria-label="Collapse sidebar" title="Collapse sidebar">${icon('chevron')}</button>`}</div><nav>${business?`<button class="nav-item" data-module="home" title="Workspace" ${route.module==='home'?'aria-current="page"':''}><span class="nav-symbol">${icon('home')}</span><span class="nav-text">Workspace</span></button>`:''}${navigation()}</nav><div class="sidebar-foot"><div class="context-title">Workspace switcher</div><a href="/">Business workspace</a><a href="/subscriptions/">SA7EN subscriptions</a><a href="/operator/">Operator administration</a><small>Sample contexts - no access grant</small>${business?'<a href="/#module=design&tab=library">Workflow library</a>':''}</div></aside><div class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><button class="search-launch" data-action="search"><span>${icon('search')} ${business?'Search this business':portal==='operator'?'Search platform operations':'Search subscribers and billing'}</span><kbd>Ctrl K</kbd></button><div class="top-context">${business?`<span class="company-context" title="Active business. Switch by signing out and signing in to another business.">${e(demoCompany)}</span><label class="sr-only" for="demo-role">Sample role</label><select id="demo-role" class="role-context">${['Owner','Bookkeeper','Storekeeper','Cashier'].map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select>`:'<span class="badge">Vendor workspace - sample</span>'}<button class="icon-button" data-action="theme" aria-label="Switch light or dark theme">${icon('theme')}</button><span class="avatar" title="Sample identity">${business?'DS':portal==='operator'?'OP':'SA'}</span></div></header><main class="workspace"><div class="print-only"></div><div class="crumbs"><button data-action="back" ${historyIndex>0?'':'disabled'} aria-label="Previous view" title="Back">${icon('arrow-left')}</button><button data-action="forward" ${historyIndex<history.length-1?'':'disabled'} aria-label="Next view" title="Forward">${icon('arrow-right')}</button><span>/</span><span>${business?'Business workspace':portal==='operator'?'Operator administration':'SA7EN subscriptions'}</span>${m?`<span>/</span><button data-module="${m.id}">${e(m.title)}</button>`:''}</div>${content()}</main></div></div>`;bindPage();}

function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${e(demoCompany)} - Synthetic company</div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,note])=>`<section class="stat"><span class="stat-label">${e(label)}</span><strong class="value">${e(value)}</strong><small>${e(note)}</small></section>`).join('')}</div>`;}
function moduleCards(ms){return `<div class="module-grid">${ms.map(m=>`<button class="module-card" data-module="${m.id}"><div class="card-icon"><span aria-hidden="true">${symbols[m.id]}</span>${badge(m.interactive?'Interactive example':'Specification brief')}</div><h3>${e(m.title)}</h3><p>${e(m.description)}</p><small>${m.requirements.length} mapped requirements &nbsp; ↗</small></button>`).join('')}</div>`;}
function home(){const preferred=favorites.length?catalog.modules.filter(m=>favorites.includes(m.id)&&!platformModules.has(m.id)):['accounting','sales','purchases','payments','banking','inventory'].map(id=>catalog.modules.find(m=>m.id===id));return `<section class="home-hero"><div><div class="eyebrow">${e(demoCompany)} - Sample workspace</div><h1>Workspace</h1><p>Choose a module or continue an accounting workflow.</p><button class="button" data-module="accounting">Open accounting</button></div><div class="hero-side"><button data-example="sales">Prepare an invoice ${icon('chevron')}</button><button data-example="payments">Record a payment ${icon('chevron')}</button><button data-module="accounting" data-tab="ledger">Find a ledger entry ${icon('chevron')}</button></div></section><div class="home-section-title"><h2>${favorites.length?'Your shortcuts':'Everyday work'}</h2><span class="muted">Connected business modules</span></div>${moduleCards(preferred)}<div class="two-column"><section class="panel"><div class="panel-head"><h2>Pick up a workflow</h2></div><div class="panel-body"><div class="quiet-row"><div><strong>Review the books</strong><small>Chart, journals, ledger and statements in one place</small></div><button class="text-button" data-module="accounting">Open</button></div><div class="quiet-row"><div><strong>Manage a project</strong><small>Tasks, time and commitments - separate from CRM</small></div><button class="text-button" data-module="projects">Open</button></div><div class="quiet-row"><div><strong>Follow up an opportunity</strong><small>Contacts, leads and pipeline</small></div><button class="text-button" data-module="crm">Open</button></div></div></section><section class="panel"><div class="panel-head"><h2>Your business settings</h2></div><div class="panel-body"><div class="quiet-row"><div><strong>People & permissions</strong><small>Company access, custom roles and workflow rules</small></div><button class="text-button" data-module="admin">Open</button></div><div class="quiet-row"><div><strong>Your SA7EN subscription</strong><small>Your plan and SA7EN invoices, separate from Sales</small></div><button class="text-button" data-module="subscription">Open</button></div><p class="form-note">Frontend build in progress. Records and workflow actions here are examples; posting is not connected.</p></div></section></div>`;}

function stateToolbar(){return `<details class="review-controls"><summary>Preview interaction states</summary><div class="state-toolbar"><span>Interaction review · <strong>${e(role)}</strong> persona · not live authorization</span><label>Preview state &nbsp;<select id="design-state">${['sample','empty','loading','denied','validation','stale','review','offline','conflict','suspended','queued','unsaved','partial-failure'].map(s=>`<option ${s===uiState?'selected':''}>${s}</option>`).join('')}</select></label></div></details>`;}
function stateMessage(){const messages={denied:['Access is restricted','This view demonstrates a resource denial. Real restrictions must also apply to search, totals, exports and direct API calls.'],loading:['Loading the permitted records','A loading-state demonstration. No request is being sent.'],suspended:['New operations are unavailable','The design preserves historical records and billing/recovery routes when a subscription is suspended.'],queued:['Accepted into the design queue, not posted','A real background job must retain an idempotent command and show durable completion or a recoverable failure. This is a state illustration.'],'partial-failure':['Some results need attention','A batch must distinguish committed records from rejected or unknown outcomes. Never retry the entire financial batch with new operation IDs.'],conflict:['This change needs reconciliation','The local example conflicts with a newer policy or record. Compare versions and retain the original evidence.']};const value=messages[uiState];if(!value)return '';return `<section class="panel empty"><div class="empty-mark">${uiState==='loading'?'':''}</div><h2>${value[0]}</h2><p>${value[1]}</p>${uiState==='loading'?'<div class="skeleton"></div><div class="skeleton short"></div>':btn('Return to sample state','sample')}${uiState==='conflict'?btn('Compare synthetic versions','conflict'):''}</section>`;}
function content(){if(route.module==='home')return home();const m=module(),r=req(route.screen);const acctEditor=m.id==='accounting'&&route.mode==='editor';const settingsEditor=m.id==='settings'&&route.mode==='editor';const opsEditor=['inventory','manufacturing','assets'].includes(m.id)&&route.mode==='editor';const meta=acctEditor?accountingUI.formMeta(route.tab,route.code,route.form):settingsEditor?{title:'Edit '+(route.form||'setting'),description:'Saving returns to the Accounting settings tab.'}:opsEditor?{title:(route.code?'Edit ':'New ')+route.form.replace(/-/g,' '),description:'Fill this form and save; it returns to the register.'}:null;const page=route.mode==='editor'?null:PAGE(m.id,route.tab);const pageLabel=(acctEditor||settingsEditor||opsEditor)?meta.title:(page?page[1]:(route.mode==='editor'?'New '+(labels[m.id]?.[0]??'design example'):(r?.title??m.title)));
 const pageDesc=(acctEditor||settingsEditor||opsEditor)?meta.description:(page?page[2]:(route.mode==='editor'?'Draft · no ledger effect until this entry is posted':m.description));
 let h=heading(pageLabel,pageDesc,route.mode==='editor'?btn('Back to register','back-register'):btn(favorites.includes(m.id)?'Favorited':'Add to favorites','favorite')+(m.interactive?((m.id==='accounting'?accountingUI.newLabel(route.tab):'New '+labels[m.id][0])?btn(m.id==='accounting'?accountingUI.newLabel(route.tab):'New '+labels[m.id][0],'new','',true):''):btn('Review workflow contracts','library')));h+=stateToolbar();if(!personaCan(m.id))return h+'<section class="panel empty"><div class="empty-mark">?</div><h2>Outside this demonstration persona</h2><p>Switch the persona to review this module. In the real application the server must enforce these restrictions independently.</p></section>';if(['denied','loading','suspended','conflict','queued','partial-failure'].includes(uiState))return h+stateMessage();if(uiState==='offline')h+='<div class="callout"><strong>Offline-state demonstration.</strong> A registered companion would retain local evidence and show sync status. This webpage is not that offline application.</div>';if(uiState==='stale')h+='<div class="callout"><strong>Preview expired.</strong> The underlying policy or record changed. A real command must require a fresh preview before posting.</div>';if(m.id==='inventory'&&route.tab==='items')return h+(route.mode==='editor'?accountingUI.editor('items',route.code):accountingUI.view('items'));
if(m.id==='inventory')return h+(route.mode==='editor'?inventory.editor(route.form,route.code):inventory.view(route.tab));
if(m.id==='tax')return h+(route.mode==='editor'?accountingUI.editor('taxes',route.code):accountingUI.taxPage(route.tab));
if(m.id==='reports')return h+accountingUI.reportPage(route.tab);
if(m.id==='manufacturing')return h+(route.mode==='editor'?manufacturing.editor(route.form,route.code):manufacturing.view(route.tab));
if(m.id==='assets')return h+(route.mode==='editor'?assets.editor(route.form,route.code):assets.view(route.tab));
if(route.mode==='editor')return h+(m.id==='accounting'?accountingUI.editor(route.tab,route.code,route.form):m.id==='settings'?accountingUI.settingsEditor(route.form,route.code):['sales','purchases'].includes(m.id)?detailed.invoiceEditor(m.id==='purchases'):editor());if(r)return h+brief(r);if(m.id==='accounting'&&route.tab!=='library')return h+accountingUI.view(route.tab);
if(m.id==='settings')return h+(route.mode==='editor'?accountingUI.settingsEditor(route.form,route.code):accountingUI.settings(route.tab));
if(m.id==='projects'&&route.tab==='projects')return h+projectsScreen(demoCompany);
if(PAGE_MAP[m.id]&&page&&page[3]!=='built')return h+plannedPage(m.id,route.tab);if(m.id==='tax'&&route.tab==='workspace')return h+detailed.tax();if(m.id==='apps'&&route.tab==='workspace')return h+detailed.apps();if(m.id==='admin'&&route.tab==='workspace')return h+portals.businessAdmin();if(m.id==='commerce')return h+portals.commerce(route.tab);if(m.id==='operator')return h+portals.operator(route.tab);if(m.id==='subscription')return h+portals.subscription();if(['projects','crm'].includes(m.id)&&route.tab==='workspace')return h+portals.projects(m.id==='crm');h+=`<div class="tabs" role="tablist" aria-label="Module views">${[['workspace','Workspace'],['register','Records'],['library','Workflow library']].map(([id,label])=>`<button role="tab" aria-selected="${route.tab===id}" data-tab="${id}">${label}</button>`).join('')}</div>`;if(m.id==='pos'&&route.tab==='workspace')return h+posCheckout();if(route.tab==='library'||m.id==='design')return h+library(m);if(route.tab==='register')return h+register(m);return h+moduleWorkspace(m);}
function moduleWorkspace(m){const rs=records.filter(r=>(!r.company||r.company===demoCompany)&&r.module===m.id);return stats([['Open demonstration records',rs.length,'Synthetic record set'],['Requires a review','2','Policy demonstration'],['Mapped requirements',m.requirements.length,'Full scope retained'],['Design status',m.interactive?'Interactive draft':'Specification','Backend status is separate']])+`<div class="two-column"><section class="panel"><div class="panel-head"><h2>${e(labels[m.id]?.[1]??'Explore '+m.title)}</h2><button class="text-button" data-tab="register">View all ↗</button></div>${table(rs.slice(0,4))}</section><section class="panel"><div class="panel-head"><h2>Connected workflows</h2></div><div class="panel-body">${connections(m.id).map(id=>{const target=catalog.modules.find(x=>x.id===id);return `<div class="activity-item"><span class="activity-dot"></span><div><button class="text-button" data-module="${id}">${e(target.title)} ↗</button><small>${e(target.description)}</small></div></div>`;}).join('')}</div></section></div><section class="panel"><div class="panel-head"><h2>Capabilities and configuration</h2><button class="text-button" data-tab="library">All ${m.requirements.length} requirements ↗</button></div><div class="panel-body">${cards(m.requirements.slice(0,6),m.id)}</div></section>`;}
function connections(mid){const map={accounting:['sales','payments','reports','settings'],banking:['payments','accounting','reports'],payments:['sales','purchases','banking','tax'],sales:['payments','inventory','tax','accounting'],purchases:['inventory','payments','assets','tax'],inventory:['purchases','manufacturing','pos','accounting'],manufacturing:['inventory','pos','projects','accounting'],pos:['inventory','manufacturing','payments','offline'],tax:['sales','purchases','payments','reports'],assets:['purchases','payments','accounting','reports'],offline:['pos','inventory','settings','admin']};return map[mid]??['settings','reports','accounting'];}
function cards(ids,mid){return `<div class="coverage-grid">${ids.map(id=>{const r=req(id),isExample=primary[mid]===id;return `<button class="workflow-card" data-screen="${id}"><div class="actions">${badge(id,'plum')}${badge(isExample?'Interactive example':'Detailed interaction pending')}</div><h3>${e(r.title)}</h3><p>${e(r.supported_scope)}</p><small>Backend: ${e(r.status)} · Owner design approval pending ↗</small></button>`;}).join('')}</div>`;}
function library(m){return `<div class="callout"><strong>Coverage is not completion.</strong> Every requirement has a design route and acceptance contract. Detailed examples are interactive; remaining entries are explicit specification briefs.</div>${cards(m.requirements,m.id)}`;}
function table(rows){return `<div class="table-scroll"><table><thead><tr><th>Reference</th><th>Description / contact</th><th>Date</th><th>Lifecycle</th><th class="numeric">PKR</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="text-button" data-record="${r.id}">${e(r.reference)}</button><span class="secondary">Synthetic record</span></td><td>${e(r.name)}</td><td>${r.date}</td><td>${badge(r.state,r.state==='Review needed'?'warn':r.state==='Posted example'?'good':'')}</td><td class="numeric">${r.amount}</td></tr>`).join('')}</tbody></table></div>`;}
function register(m){const rs=uiState==='empty'?[]:records.filter(r=>(!r.company||r.company===demoCompany)&&r.module===m.id&&(!listStatus||r.state===listStatus)&&(r.reference+' '+r.name).toLowerCase().includes(listSearch.toLowerCase()));return `<section class="panel"><div class="filterbar"><label class="sr-only" for="record-search">Search synthetic records</label><input id="record-search" type="search" placeholder="Search reference or contact…" value="${e(listSearch)}"><label class="sr-only" for="record-status">Record status</label><select id="record-status"><option value="">All statuses</option>${['Draft','Review needed','Posted example','Returned'].map(s=>`<option ${s===listStatus?'selected':''}>${s}</option>`).join('')}</select>${btn('Export demo CSV','export')}</div>${rs.length?table(rs):`<div class="empty"><div class="empty-mark"></div><h2>No matching records</h2><p>Adjust your filters or start a new synthetic example. Empty results are distinct from a permission denial.</p>${m.interactive?btn('New '+labels[m.id][0],'new','',true):btn('Explore requirements','library')}</div>`}<div class="table-footer"><span>${rs.length} synthetic records · complete local example set</span><span>No business API connected</span></div></section>`;}
function brief(r){const m=module(),mapping=catalog.screens.find(s=>s.requirement===r.id&&s.module===m.id),interactive=primary[m.id]===r.id;return `<div class="callout"><strong>${interactive?'Interactive module example available.':'Specification brief · detailed interactions pending.'}</strong> This route maps the requirement and its contract. Backend state remains ${e(r.status)}; no release verification or design approval is implied.</div><div class="two-column"><section class="panel"><div class="panel-head"><h2>Scope and acceptance</h2>${badge(r.id,'plum')}</div><div class="panel-body"><h3>Required capability</h3><p class="form-note">${e(r.supported_scope)}</p><h3 class="section-title">Acceptance condition</h3><p>${e(r.acceptance)}</p><div class="related">${interactive?btn('Try the interactive example','new','',true):''}${btn('View module register','register')}${btn('Inspect contract','contract',`data-requirement="${r.id}"`)}</div></div></section><section class="panel"><div class="panel-head"><h2>Implementation boundary</h2></div><div class="panel-body"><div class="record-summary"><div><small>Design</small>${interactive?'Interactive draft':'Brief mapped'}</div><div><small>Source</small>${e(r.status)}</div><div><small>Owner approval</small>Not approved</div></div><p class="form-note">${e(catalog.workflowContracts.authority)}</p><p class="form-note">${e(catalog.workflowContracts.financial)}</p></div></section></div>`;}
const field=(name,label,value='',type='text',help='')=>`<label>${e(label)} <input name="${name}" type="${type}" value="${e(value)}" ${['reference','description','date'].includes(name)?'required':''} ${['costDisplay','residual','service','life'].includes(name)?'readonly':''} ${type==='number'?'min="0" max="10000"':''}>${help?`<small>${e(help)}</small>`:''}</label>`;
const select=(name,label,values,value='')=>`<label>${e(label)}<select name="${name}">${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${e(id)}" ${id===value?'selected':''}>${e(text)}</option>`;}).join('')}</select></label>`;
function defaultDraft(mid){return {reference:'DEMO-'+mid.slice(0,3).toUpperCase()+'-NEW',date:'2026-11-13',description:mid==='manufacturing'?'Biscuit production · recipe v3':'Synthetic '+(labels[mid]?.[0]??'workflow')+' example',party:'Atlas Studio · synthetic',branch:'Central store',quantity:'2',price:'100.00',discount:'10',rate:'10',basis:'exclusive',tracked:'no',settlement:'credit',recovery:'100',amount:mid==='tax'?'198.00':'200.00',allocated:'180.00',direction:'receive',cost:mid==='inventory'?'20.00':'40.00',movement:'receipt',material:'100.00',labour:'20.00',overhead:'10.00',production:'complete',taxBase:'180.00',withholding:'5',depreciation:'170.00',authority:'factory',files:[],lifecycle:'Design draft'};}
function capture(){const f=document.querySelector('#design-editor');if(f)draft={...draft,...Object.fromEntries(new FormData(f))};}
function moduleFields(){const p=draft,mid=route.module;const base=field('reference','Reference',p.reference)+field('date','Posting date',p.date,'date')+field('description','Description',p.description)+select('branch','Branch / warehouse',['Central store','Bakery','Workshop'],p.branch);let extra='';
if(['sales','purchases','pos'].includes(mid))extra=field('party',mid==='purchases'?'Supplier':'Customer',p.party)+select('settlement','Settlement',[['credit','Credit invoice'],['paid','Invoice + linked receipt'],['cash','Permitted direct cash']],p.settlement)+select('basis','Price tax basis',[['exclusive','Tax exclusive'],['inclusive','Tax inclusive']],p.basis)+select('tracked','Line type',[['no','Service / untracked'],['yes','Tracked inventory']],p.tracked)+field('quantity','Quantity',p.quantity,'number')+field('price','Unit price · PKR',p.price)+field('discount','Line discount · %',p.discount,'number')+field('rate','Synthetic tax rate · %',p.rate,'number')+(mid==='purchases'?field('recovery','Input tax recoverability · %',p.recovery,'number'):field('cost','Unit valuation cost · PKR',p.cost));
else if(mid==='payments')extra=select('direction','Direction',[['receive','Receive money'],['pay','Pay money']],p.direction)+field('party','Party / counterparty',p.party)+field('amount','Payment amount · PKR',p.amount)+field('allocated','Allocated to invoices · PKR',p.allocated)+select('method','Method',['Bank transfer','Cash','Cheque'],'Bank transfer')+field('bankReference','Bank / instrument reference','DEMO-TRX-026');
else if(mid==='inventory')extra=select('movement','Movement',[['receipt','Receive stock'],['issue','Issue to expense / project'],['transfer','Transfer between stores']],p.movement)+field('item','Item','Biscuit packaging · synthetic')+field('quantity','Quantity',p.quantity,'number')+field('cost','Unit valuation cost · PKR',p.cost)+select('target','Destination',['Bakery','Workshop'],'Bakery')+select('valuation','Valuation policy',['FIFO · example','Weighted average · example']);
else if(mid==='manufacturing')extra=field('bom','BOM / recipe version','BISCUIT-V3 · synthetic')+field('quantity','Planned output quantity',p.quantity,'number')+field('material','Actual materials · PKR',p.material)+field('labour','Direct labour · PKR',p.labour)+field('overhead','Applied overhead · PKR',p.overhead)+select('production','Completion',[['complete','Complete output'],['partial','Keep in WIP']],p.production);
else if(mid==='tax')extra=field('registration','Registration / jurisdiction','Synthetic profile · no statutory claim')+field('taxBase','Illustrative withholding base',p.taxBase)+field('withholding','Illustrative rate · %',p.withholding,'number')+field('amount','Supplier payable · PKR',p.amount)+select('timing','Deduction point',['At payment · example','At invoice · contract required']);
else if(mid==='assets')extra=field('asset','Asset','EQ-001 · Office equipment')+field('costDisplay','Cost · PKR','1000.00')+field('residual','Residual · PKR','100.00')+field('depreciation','Fixture depreciation · PKR',p.depreciation)+field('service','In-service date','2026-01-15','date')+field('life','Useful life · months','3','number');
else if(mid==='banking')extra=select('bankFrom','Transfer from',['1000 · Cash in hand'])+select('bankTo','Transfer to',['1010 · Operating bank'])+field('amount','Transfer amount · PKR',p.amount)+field('statement','Statement reference','DEMO-STM-026');
else extra=select('debitAccount','Debit account',['1000 · Cash in hand','1010 · Operating bank','5000 · Operating expense'],p.debitAccount)+select('creditAccount','Credit account',['3000 · Owner capital','2100 · Trade payables','1010 · Operating bank'],p.creditAccount)+field('amount','Amount · PKR',p.amount)+select('purpose','Journal purpose',['General journal','Accrual · detailed contract pending','Prepayment · detailed contract pending']);
return `<h3 class="section-title">Document details</h3><div class="form-grid">${base}${extra}${select('authority','Authority demonstration',[['factory','Factory owner / administrator rules'],['scoped-direct','Published scope permits preparer posting'],['independent','Independent review required']],p.authority)}</div><p class="form-note">These fields demonstrate the module contract. Rates, values, policy and parties are synthetic. Additional requirement-specific fields remain in the workflow library.</p>`;}
function linesView(){if(route.module==='payments')return `<h3 class="section-title">Allocate to outstanding documents</h3><p>Two synthetic invoice references. Change the allocated total in Document to see the advance balance.</p><div class="table-scroll"><table><thead><tr><th>Reference</th><th>Outstanding</th><th>Illustrative allocation</th></tr></thead><tbody><tr><td>DEMO-SAL-1001</td><td>100.00</td><td>${decimal(cents(draft.allocated)>10000n?10000n:cents(draft.allocated))}</td></tr><tr><td>DEMO-SAL-1002</td><td>80.00</td><td>${decimal(cents(draft.allocated)>10000n?cents(draft.allocated)-10000n:0n)}</td></tr></tbody></table></div>`;if(route.module==='manufacturing')return `<h3 class="section-title">Recipe and actual consumption</h3><div class="table-scroll"><table><thead><tr><th>Material / operation</th><th>Version / source</th><th>Cost</th></tr></thead><tbody><tr><td>Ingredients</td><td>BOM v3 · Central store</td><td>${e(draft.material)}</td></tr><tr><td>Direct labour</td><td>Operation 01 · mixing / baking</td><td>${e(draft.labour)}</td></tr><tr><td>Overhead</td><td>Policy v1 · illustrative</td><td>${e(draft.overhead)}</td></tr></tbody></table></div><p class="form-note">Partial completion retains cost in WIP. Scrap, by-products and jewellery ownership require their own detailed screen contracts.</p>`;return `<h3 class="section-title">Line and terms summary</h3><div class="table-scroll"><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price / cost</th><th>Discount</th><th>Tax</th></tr></thead><tbody><tr><td>${e(draft.description)}</td><td>${e(draft.quantity)}</td><td>${e(draft.price)}</td><td>${e(draft.discount)}%</td><td>${e(draft.rate)}% · synthetic</td></tr></tbody></table></div><p class="form-note">This is a single-line scenario editor. Complete multi-line editing, terms, returns and additional variants remain review items; they are not claimed complete.</p>`;}
function preview(){try{const v=illustrate(route.module,draft);return `<div class="panel-head"><h2>Illustrative accounting</h2>${badge('Design only','plum')}</div><div class="panel-body"><div class="eyebrow">${route.module==='sales'||route.module==='purchases'?'Document total':'Illustrative amount'} · PKR</div><div class="summary-number">${v.gross}</div>${v.net!=='0.00'?`<small>Net ${v.net} · Tax ${v.tax}</small>`:''}</div><div class="table-scroll"><table><thead><tr><th>Account</th><th class="numeric">Debit</th><th class="numeric">Credit</th></tr></thead><tbody>${v.entries.map(l=>`<tr><td>${e(l.account)}</td><td class="numeric">${l.debit==='0.00'?'—':l.debit}</td><td class="numeric">${l.credit==='0.00'?'—':l.credit}</td></tr>`).join('')}</tbody></table></div><div class="preview-total"><span>${v.entries.length?'Balanced illustration':'No GL movement'}</span><strong>${v.totalDebit}</strong></div><div class="preview-notes">${v.notes.map(n=>`<p>${e(n)}</p>`).join('')}<p><strong>Backend revalidation required.</strong> A live preview must use current balances, tax versions, permissions and locks. This example never posts.</p></div>`;}catch(x){return `<div class="panel-body error" role="alert">${e(x.message)}</div>`;}}
function editor(){if(!Object.keys(draft).length)draft=defaultDraft(route.module);const tabs=[['document','Document'],['lines','Lines & terms'],['evidence','Evidence'],['activity','Activity & links']];let body=editorTab==='document'?moduleFields():editorTab==='lines'?linesView():editorTab==='evidence'?`<div class="evidence-drop"><h3>Supporting documents</h3><p class="form-note">Choose local file names to review the attachment interaction. No files are uploaded or scanned.</p><input id="design-files" type="file" multiple aria-label="Select design evidence file names">${draft.files.map(n=>`<p>${e(n)} ${badge('Not uploaded / not scanned')}</p>`).join('')}</div>`:`<h3 class="section-title">Source and review trail</h3><div class="activity-item"><span class="activity-dot"></span><div>${e(draft.lifecycle)}<small>Current browser memory only · reset on reload</small></div></div><p class="form-note">Posted sources would link to immutable journals, allocations, policy and evidence versions.</p><div class="related">${connections(route.module).map(id=>`<button class="button" data-module="${id}">${e(catalog.modules.find(m=>m.id===id).title)} ↗</button>`).join('')}</div>`;return `<div class="editor-layout"><section class="panel editor"><div class="panel-head"><h2>${e(draft.reference)}</h2>${badge(draft.lifecycle,'plum')}</div><div class="tabs" role="tablist" aria-label="Document sections">${tabs.map(([id,title])=>`<button role="tab" aria-selected="${editorTab===id}" data-editor-tab="${id}">${title}${id==='evidence'&&draft.files.length?' ('+draft.files.length+')':''}</button>`).join('')}</div><form id="design-editor" class="panel-body">${body}<div id="design-validation" class="error" role="alert">${uiState==='validation'?'Example validation: a source reference is required before a live command can be submitted.':''}</div></form><div class="lifecycle"><span class="active">Design draft</span><span>→</span><span>Preview / authority</span><span>→</span><span>Review or direct posting</span><span>→</span><span>Source & ledger</span></div><div class="panel-head"><span class="muted">${dirty?'Unsaved design changes':'Synthetic example'}</span><div class="actions">${btn('Inspect workflow contract','contract',`data-requirement="${primary[route.module]}"`)}${btn(draft.authority==='independent'?'Simulate review route':'Simulate authorized posting','simulate',uiState==='stale'?'disabled':'',true)}</div></div></section><aside class="panel preview-panel" id="design-preview" aria-live="polite">${preview()}</aside></div>`;}
function bindPage(){accountingUI.bind();inventory.bind(render,notify,go);manufacturing.bind(render,notify,go);assets.bind(render,notify,go);detailed.bind(route.module);document.querySelector('#design-state')?.addEventListener('change',ev=>{capture();uiState=ev.target.value;if(uiState==='unsaved')dirty=true;render();});document.querySelector('#demo-role')?.addEventListener('change',ev=>{capture();role=ev.target.value;render();notify('Demonstration persona changed. This does not change real permissions.');});document.querySelector('#demo-branch')?.addEventListener('change',ev=>{demoBranch=ev.target.value;render();});document.querySelector('#record-search')?.addEventListener('input',ev=>{const pos=ev.target.selectionStart;listSearch=ev.target.value;render();const f=document.querySelector('#record-search');f.focus();f.setSelectionRange(pos,pos);});document.querySelector('#record-status')?.addEventListener('change',ev=>{listStatus=ev.target.value;render();});const f=document.querySelector('#design-editor');f?.addEventListener('submit',ev=>ev.preventDefault());f?.addEventListener('input',()=>{capture();dirty=true;document.querySelector('#design-preview').innerHTML=preview();});f?.addEventListener('change',()=>{capture();dirty=true;document.querySelector('#design-preview').innerHTML=preview();});document.querySelector('#design-files')?.addEventListener('change',ev=>{draft.files=[...ev.target.files].map(f=>f.name);dirty=true;render();});}
function openRecord(id){const r=records.find(r=>r.id===id);if(!r)return;if(!personaCan(r.module)||r.company&&r.company!==demoCompany){notify('This synthetic record is outside the selected persona or company.');return;}const v=primary[r.module]?illustrate(r.module,defaultDraft(r.module)):null;detailDialog.innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">Synthetic record · not a business document</div><h2 id="detail-title">${e(r.reference)}</h2></div><button class="icon-button" data-close="detail" aria-label="Close record">${icon('close')}</button></div><div class="dialog-content"><div class="record-summary"><div><small>Contact / description</small>${e(r.name)}</div><div><small>Posting date</small>${r.date}</div><div><small>Lifecycle</small>${badge(r.state,'plum')}</div></div><div class="related">${btn('Open module example','record-example',`data-example-module="${r.module}"`)}${btn('Print design example','print')}</div><div class="callout"><strong>Connected source trail.</strong> A real record would retain its journal, exact policy decision, evidence versions and linked settlements. The links below navigate synthetic module views.</div><div class="related">${connections(r.module).map(id=>`<button class="button" data-related-module="${id}">${e(catalog.modules.find(m=>m.id===id).title)} ↗</button>`).join('')}</div>${v?`<h3 class="section-title">Illustrative journal</h3><div class="table-scroll"><table><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${v.entries.map(l=>`<tr><td>${e(l.account)}</td><td>${l.debit}</td><td>${l.credit}</td></tr>`).join('')}</tbody></table></div>`:'<p class="form-note">This area is a specification brief. No financial effect or implemented workflow is implied. Open its library to review the typed fields and acceptance contract.</p>'}</div>`;detailDialog.showModal();}
function contract(id){const r=req(id);if(!r)return;const mapping=catalog.screens.find(s=>s.requirement===id);detailDialog.innerHTML=`<div class="dialog-heading"><h2 id="detail-title">${e(r.id)} · Workflow contract</h2><button class="icon-button" data-close="detail" aria-label="Close contract">${icon('close')}</button></div><div class="dialog-content"><h3>${e(r.title)}</h3><p class="form-note">${e(r.supported_scope)}</p><h3 class="section-title">Pass / fail acceptance</h3><p>${e(r.acceptance)}</p><h3 class="section-title">Authority</h3><p>${e(catalog.workflowContracts.authority)}</p><h3 class="section-title">Financial boundary</h3><p>${e(catalog.workflowContracts.financial)}</p><h3 class="section-title">Typed field contract</h3><div class="table-scroll"><table><thead><tr><th>Field</th><th>Type / constraints</th><th>Required</th></tr></thead><tbody>${(catalog.workflowContracts.modules[mapping.module]?.fields??[]).map(f=>`<tr><td>${e(f.name)}</td><td>${e(f.type)}</td><td>${f.required?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div><h3 class="section-title">Version and evidence</h3><p>${e(mapping.contract)} · source status ${e(r.status)} · owner design approval NOT_APPROVED.</p><p class="form-note">A canonical command needs authenticated actor/tenant/company, command version, exact payload, idempotency key, record/policy/evidence versions and correlation ID. This is a design contract, not a callable API schema.</p></div>`;detailDialog.showModal();}
let matches=[],selected=0,searchOrigin;
function openSearch(){matches=[];selected=0;searchOrigin=document.activeElement;searchDialog.innerHTML=`<div class="search-input-wrap"><label id="search-title" class="sr-only" for="global-search">Search the synthetic product library</label><input id="global-search" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="global-results" placeholder="Search accounts, invoices, workflows, settings…" autocomplete="off"></div><div id="global-results" class="search-results" role="listbox"></div><div class="search-hint">↑ ↓ to choose · Enter to open · Esc to close · Synthetic library only</div>`;searchDialog.showModal();const input=searchDialog.querySelector('input');input.addEventListener('input',()=>{matches=searchIndex(personaCatalog(),records.filter(r=>personaCatalog().modules.some(m=>m.id===r.module)&&(!r.company||r.company===demoCompany)),input.value);selected=0;renderMatches();});input.addEventListener('keydown',ev=>{if(['ArrowDown','ArrowUp'].includes(ev.key)){ev.preventDefault();selected=Math.max(0,Math.min(matches.length-1,selected+(ev.key==='ArrowDown'?1:-1)));renderMatches();}if(ev.key==='Enter'&&matches[selected]){ev.preventDefault();chooseMatch(selected);}});renderMatches();input.focus();}
function renderMatches(){const el=searchDialog.querySelector('#global-results');el.innerHTML=matches.length?matches.map((m,i)=>`<button class="search-result" id="match-${i}" role="option" aria-selected="${i===selected}" data-search-match="${i}"><span><strong>${e(m.title)}</strong><small>${e(m.subtitle)}</small></span>${badge(m.type)}</button>`).join(''):'<div class="panel-body"><p>Search all mapped modules, workflows and synthetic records. Try “journal”, “withholding”, “manufacturing” or “DEMO-SAL”.</p></div>';const input=searchDialog.querySelector('input');if(matches.length)input.setAttribute('aria-activedescendant','match-'+selected);else input.removeAttribute('aria-activedescendant');el.querySelector('[aria-selected=true]')?.scrollIntoView({block:'nearest'});}
function chooseMatch(i){const m=matches[i];if(!m)return;searchDialog.close();if(m.record){go({module:m.module,tab:'register'});openRecord(m.record);}else go({module:m.module,screen:m.screen??'',tab:m.screen?'library':'workspace'});}
searchDialog.addEventListener('close',()=>searchOrigin?.focus());
function exportDemo(){if(!personaCan(route.module)){notify('This demonstration persona cannot export this module.');return;}const rows=[['SA7EN SYNTHETIC DESIGN DATA','Not a business export'],['Reference','Description','Date','Design lifecycle','Illustrative PKR'],...records.filter(r=>r.module===route.module&&(!r.company||r.company===demoCompany)).map(r=>[r.reference,r.name,r.date,r.state,r.amount])];const text=rows.map(row=>row.map(x=>'"'+(/^[\s\u0000-\u001f]*[=+@-]/.test(String(x))?"'":'')+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='SA7EN-synthetic-design-'+route.module+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const products=[{id:'biscuits',name:'Butter biscuits',unit:'Box · recipe v3',price:'100.00',cost:'40.00',symbol:''},{id:'coffee',name:'Coffee blend',unit:'Bag · Central store',price:'150.00',cost:'90.00',symbol:''},{id:'notebook',name:'Studio notebook',unit:'Each · Central store',price:'200.00',cost:'120.00',symbol:''},{id:'bread',name:'Sourdough loaf',unit:'Each · recipe v2',price:'120.00',cost:'60.00',symbol:''},{id:'packaging',name:'Gift packaging',unit:'Each · untracked',price:'50.00',cost:'20.00',symbol:''},{id:'service',name:'Custom finishing',unit:'Service · no stock',price:'80.00',cost:'0.00',symbol:''}];
let cart=[],tender='Cash',shiftReceipts=0n;
function cartTotals(){const rows=cart.map(r=>{const p=products.find(p=>p.id===r.id),v=illustrate('pos',{quantity:String(r.quantity),price:p.price,cost:p.cost,discount:'0',rate:'10',basis:'exclusive'});return {...p,quantity:r.quantity,...v};});return {rows,total:rows.reduce((s,r)=>s+cents(r.gross),0n)};}
function posCheckout(){const c=cartTotals();return `<div class="callout"><strong>Counter 01 · synthetic shift.</strong> Tap products or use search. Tax 10% is illustrative. Recipe/stock effects need approved production and valuation contracts.</div><div class="pos-layout"><section><div class="product-grid">${products.map(p=>`<button class="product" data-pos-add="${p.id}"><span class="product-symbol" aria-hidden="true">${p.symbol}</span><strong>${p.name}</strong><small>${p.unit}</small><small>PKR ${p.price} + illustrative tax</small></button>`).join('')}</div><div class="related">${btn('Review shift close','pos-shift')}${btn('Returns workflow','pos-returns')}${btn('Offline and sync','pos-offline')}</div></section><section class="panel"><div class="panel-head"><h2>Current sale</h2>${badge('Design cart','plum')}</div>${c.rows.length?`<div class="table-scroll"><table><thead><tr><th>Item</th><th>Qty</th><th class="numeric">Total</th><th></th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${r.name}</td><td>${r.quantity}</td><td class="numeric">${r.gross}</td><td><button class="text-button" data-pos-remove="${r.id}" aria-label="Remove one ${r.name}">−</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-mark"></div><h2>Ready for a new sale</h2><p>Add products to inspect tax, tender and illustrative stock effects.</p></div>'}<div class="panel-body"><div class="preview-total"><strong>Total · PKR</strong><strong class="summary-number">${decimal(c.total)}</strong></div><div class="form-grid">${select('tender','Tender',['Cash','Bank / card','Split tender'],tender)}</div><p class="form-note">All payment methods are simulations. No terminal, stock or ledger is connected.</p><div class="related">${btn('Simulate checkout','pos-checkout',c.total?'':'disabled',true)}${btn('Clear cart','pos-clear')}</div></div></section></div>`;}
function beginExample(mid){if(dirty&&!confirm('Discard this unsaved design draft?'))return;dirty=false;draft=defaultDraft(mid);editorTab='document';go({module:mid,mode:'editor'});}
document.addEventListener('change',ev=>{if(ev.target.name==='tender')tender=ev.target.value;});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.posAdd){const row=cart.find(r=>r.id===b.dataset.posAdd);if(row)row.quantity++;else cart.push({id:b.dataset.posAdd,quantity:1});render();}if(b.dataset.posRemove){const row=cart.find(r=>r.id===b.dataset.posRemove);if(row)row.quantity--;cart=cart.filter(r=>r.quantity>0);render();}if(b.dataset.action==='pos-clear'){cart=[];render();}if(b.dataset.action==='pos-checkout'){const c=cartTotals();if(!c.total)return;shiftReceipts+=c.total;cart=[];render();notify('Checkout simulation complete · '+decimal(c.total)+' PKR via '+tender+'. No real sale, payment or stock movement.');}if(b.dataset.action==='pos-shift'){detailDialog.innerHTML=`<div class="dialog-heading"><h2 id="detail-title">Shift close · synthetic example</h2><button class="icon-button" data-close="detail" aria-label="Close shift">${icon('close')}</button></div><div class="dialog-content"><div class="record-summary"><div><small>Opening float</small>1,000.00</div><div><small>Simulated gross receipts</small>${decimal(shiftReceipts)}</div><div><small>Expected total before tender split</small>${decimal(100000n+shiftReceipts)}</div></div><p class="form-note">This illustrative total is not a reconciled cash drawer. Cash/card split, refunds, counted cash and independently approved variances need detailed design review.</p></div>`;detailDialog.showModal();}if(b.dataset.action==='pos-returns')go({module:'pos',screen:'POS-005'});if(b.dataset.action==='pos-offline')go({module:'offline'});});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if(!searchDialog.open)openSearch();}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.close){detailDialog.close();return;}if(b.dataset.searchMatch!==undefined){chooseMatch(Number(b.dataset.searchMatch));return;}if(b.dataset.relatedModule){detailDialog.close();go({module:b.dataset.relatedModule});return;}if(b.dataset.example){beginExample(b.dataset.example);return;}if(b.dataset.module){go({module:b.dataset.module,tab:b.dataset.tab??'workspace'});mobileMenu=false;return;}if(b.dataset.screen){go({module:route.module,screen:b.dataset.screen});return;}if(b.dataset.record){openRecord(b.dataset.record);return;}if(b.dataset.editorTab){capture();editorTab=b.dataset.editorTab;render();return;}if(b.dataset.tab){go({module:route.module,tab:b.dataset.tab});return;}
switch(b.dataset.action){case 'search':matches=[];openSearch();break;case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('saven:design:v2:theme',theme);}catch{}break;}case 'menu':mobileMenu=!mobileMenu;render();break;case 'back':move(-1);break;case 'forward':move(1);break;case 'coverage':go({module:'design',tab:'library'});break;case 'library':go({module:route.module,tab:'library'});break;case 'register':go({module:route.module,tab:'register'});break;case 'back-register':go({module:route.module,tab:route.tab});break;case 'new':if(route.module==='accounting'){accountingUI.prepareNew(route.tab);go({module:'accounting',tab:route.tab,mode:'editor',code:''});}else if(route.module==='inventory'){go({module:'inventory',tab:'receipts',mode:'editor',form:'receipt',code:''});}else if(route.module==='manufacturing'){go({module:'manufacturing',tab:'orders',mode:'editor',form:'order',code:''});}else if(route.module==='assets'){go({module:'assets',tab:'register',mode:'editor',form:'asset',code:''});}else{beginExample(route.module);}break;case 'sample':uiState='sample';render();break;case 'favorite':favorites=favorites.includes(route.module)?favorites.filter(x=>x!==route.module):[...favorites,route.module];try{localStorage.setItem('saven:design:v2:favorites',JSON.stringify(favorites));}catch{}render();break;case 'contract':contract(b.dataset.requirement);break;case 'record-example':{const m=b.dataset.exampleModule;detailDialog.close();if(!primary[m]){go({module:m,tab:'library'});break;}draft=defaultDraft(m);editorTab='document';go({module:m,mode:'editor'});break;}case 'print':window.print();break;case 'export':exportDemo();break;case 'simulate':capture();illustrate(route.module,draft);if(uiState==='validation'){notify('Validation-state demonstration: resolve required fields before a live preview.');break;}if(!draft.reference?.trim()||!draft.description?.trim()){document.querySelector('#design-validation').textContent='Reference and description are required.';break;}draft.lifecycle=draft.authority==='independent'||uiState==='review'||role!=='Owner'&&draft.authority!=='scoped-direct'?'Simulated review route':'Simulated direct-post route';dirty=false;render();notify('Simulation complete. No transaction was posted or submitted.');break;case 'conflict':detailDialog.innerHTML=`<div class="dialog-heading"><h2 id="detail-title">Synthetic conflict review</h2><button class="icon-button" data-close="detail" aria-label="Close conflict">${icon('close')}</button></div><div class="dialog-content"><div class="record-summary"><div><small>Local evidence</small>DEMO-OFF-1001 · policy v2</div><div><small>Central state</small>Period closed · policy v3</div><div><small>Resolution</small>Authorized review required</div></div><p class="form-note">Retain both versions and the original operation ID. No silent rewrite, duplicate journal or actual synchronization occurs here.</p></div>`;detailDialog.showModal();break;}}catch(x){notify(x.message);}});
window.addEventListener('hashchange',readRoute);window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue='';}});readRoute();

document.addEventListener('click',event=>{if(event.target.closest('[data-action=collapse]')){sidebarCollapsed=true;render();return;}if(event.target.closest('[data-action=expand]')){sidebarCollapsed=false;render();}});
